  "arguments": {
    "code": "const source=await figma.getNodeByIdAsync('6:3'); if(!source||source.type!=='FRAME') throw new Error('Source mark missing'); const ink={r:23/255,g:27/255,b:25/255}, chalk={r:245/255,g:245/255,b:238/255}; const solid=c=>[{type:'SOLID',color:c}]; const board=figma.createFrame(); board.name='Sandbox Kit / Box — selected direction'; board.x=1760; board.y=80; board.resize(1600,450); board.fills=solid(chalk); const left=source.clone(); board.appendChild(left); left.name='Box / Ink on Chalk'; left.x=0; left.y=0; const right=source.clone(); board.appendChild(right); right.name='Box / Chalk on Ink'; right.x=800; right.y=0; right.fills=solid(ink); const clean=panel=>{const mark=panel.children[0]; mark.name='Sandbox Kit / box'; for(const c of [...mark.children]) if(c.type==='VECTOR'&&c.y<0)c.remove(); return mark;}; const lmark=clean(left),rmark=clean(right); for(const c of rmark.children){if(c.type==='VECTOR'&&c.fills.length) c.fills=solid(chalk); if(c.type==='VECTOR'&&c.strokes.length) c.strokes=solid(ink);} const all=[]; const walk=n=>{all.push(n.id); if('children' in n) for(const c of n.children)walk(c)}; walk(board); return {createdNodeIds:all,boardId:board.id,markIds:[lmark.id,rmark.id],boards:board.children.map(n=>({id:n.id,name:n.name,x:n.x,y:n.y,width:n.width,height:n.height}))};",
    "description": "Present user's plain box as the new monochrome logo direction",
    "fileKey": "REDACTED",
    "skillNames": "figma-use"
  },
