    "code": "const source=await figma.getNodeByIdAsync('8:4'); if(!source||source.type!=='FRAME') throw new Error('Selected box mark missing'); const chalk={r:245/255,g:245/255,b:238/255}; const solid=c=>[{type:'SOLID',color:c}]; const board=figma.createFrame(); board.name='Sandbox Kit / Social + GitHub avatars'; board.x=1760; board.y=650; board.resize(1800,1150); board.fills=solid(chalk); const specs=[{name:'Social avatar / 1024 × 1024',size:1024,x:40,y:40},{name:'GitHub avatar / 500 × 500',size:500,x:1170,y:40},{name:'X avatar / 400 × 400',size:400,x:1220,y:640}]; const assets=[]; const ids=[board.id]; for(const spec of specs){const frame=figma.createFrame(); board.appendChild(frame); frame.name=spec.name; frame.x=spec.x; frame.y=spec.y; frame.resize(spec.size,spec.size); frame.fills=solid(chalk); const mark=source.clone(); frame.appendChild(mark); mark.name='Sandbox Kit / box'; mark.rescale(spec.size*0.82/350); mark.x=(spec.size-mark.width)/2; mark.y=(spec.size-mark.height)/2; ids.push(frame.id,mark.id,...mark.children.map(n=>n.id)); assets.push({id:frame.id,name:frame.name,size:spec.size,markId:mark.id,markBounds:{x:mark.x,y:mark.y,width:mark.width,height:mark.height}});} return {createdNodeIds:ids,boardId:board.id,assets};",
    "description": "Create export-ready square logo frames for social avatars and GitHub",
    "fileKey": "REDACTED",
    "skillNames": "figma-use"
